-- Bug Fix v2 in the platform library (board task 5e654dd1, stage 7).
--
-- WHY: on the VibeCodes board, one standard-tier engineer doing "Investigate and
-- fix" (handing back "ESCALATE" for the top model when it cannot pin the cause)
-- cost about 5 dollars a bug against about 13 for the old Planner + Fix pair, with
-- no wrong diagnoses and fewer review send-backs. The owner approved rolling it
-- out on 25 Oct 2026; the board copies were switched the same day. This brings the
-- library (what new boards copy) into line.
--
-- 1. Bug Fix: Investigate and plan the fix (Planner, frontier) + Fix (standard)
--    become one Investigate and fix step (Full Stack Engineer, standard). Code
--    review (frontier) and Verify and release summary (standard, approval) keep
--    their text apart from the reset target.
-- 2. Game Bug Fix: the same merge; the regression playtest stays last.
--
-- Data only, no schema change. Pinned by src/lib/workflow-library-bugfix-v2.test.ts.
-- Tables and columns used: workflow_library_templates (steps, description,
-- updated_at, name), the same ones 00189 updates.

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Full Stack Engineer","title":"Investigate and fix","model_tier":"standard","description":"Reproduce the bug and write down the exact steps. Find the root cause, not just where the symptom shows: trace it through the code, explain why it happens, and say when it started if the data shows it. Name the files and functions involved and anything else that shares the same cause. If you can't reproduce it, say so plainly with the evidence you do have; don't present a guess as confirmed. If the fix would change what users see, or touches stored data, auth or payments, say so at the top. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are.\n\nKeep the investigation lean. The card and its description are in your brief; read the card again only if something you need is missing. Search narrowly (file paths, line numbers) and read only the lines you need, at most about 150 at a time; don't print whole large files. Do all searching yourself: don't start helper agents (they can run on the top model and cost more). Batch independent look-ups into one turn. Aim to finish within about 40 actions. Take a screenshot only when the bug is visual, one per check.\n\nEscalation: if after about 60 actions you have neither a failing test nor a confirmed reproduction that pins the cause, or you can only explain the symptom and not the cause, stop. Save your findings and hand back a first line starting \"ESCALATE: needs the top model\", then what you proved, what you ruled out and where you'd look next. Don't write a speculative fix.\n\nThen fix the root cause, test first: write a test that reproduces the bug and fails before you change any code, then make it pass. Keep the change to the bug. Add what you decided and why to the working-notes file, and commit it with your work. Your output names the test that failed and then passed, and confirms the full test suite and type checker pass.\n\nOn rework from review or verify: keep the diagnosis unless the feedback says it is wrong; go straight to the fix. If the root cause turns out to be different, don't patch the symptom: say so plainly in your output.\n\nFor the session running this workflow: if this step's hand-back starts 'ESCALATE', don't complete the step. Call fail_step on it with reset_to_step_id = this step and the hand-back as output, then update_step it to model_tier frontier, then claim_next_step again. If the step is already on frontier, stop and ask the person instead.","deliverables":["Reproduction steps","Root cause","Fix and regression test (failed before, passes after)","PR link","Test suite and type checker passing","Working-notes file"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the fix independently against the root cause in the investigation and the working-notes file. You don't edit code. Check that it fixes the cause rather than the symptom, that the regression test really fails without the fix, and look for security issues, test quality, project conventions and scope creep. Send blocking issues back with fail_step as a numbered list: reset to Investigate and fix, saying whether the diagnosis or the code is wrong. Start your output with 'Pass' or 'Blocked'.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Verify and release summary","model_tier":"standard","description":"Check the fix independently of the builder. Follow the original reproduction, on the live site if it has been released, otherwise on a local or preview build, and confirm the bug is gone. Read the regression test and confirm it would fail if the bug came back. Check the behaviour around the change. Send failures back with fail_step: reset to Investigate and fix, saying whether the diagnosis or the code is wrong. Then write the release summary in plain English: what's fixed, how you checked, and anything still needing a person. The release is approved from this step.","deliverables":["Verification against the original reproduction","Nearby behaviour checked","Plain-English release summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Diagnose and fix, check, verify: one standard-tier engineer finds the root cause and fixes it test-first, handing back to the top model if it can't pin the cause; an independent top-model code review and an independent verification follow, and you approve the release.$tpl$,
    updated_at = now()
WHERE name = $tpl$Bug Fix$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Full Stack Engineer","title":"Investigate and fix","model_tier":"standard","description":"Reproduce the bug and write down the exact steps. Find the root cause, not just where the symptom shows: explain why it happens, and name the scripts or scenes involved. If you can't reproduce it, say so plainly with the evidence you do have; don't present a guess as confirmed. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are.\n\nKeep the investigation lean. The card and its description are in your brief; read the card again only if something you need is missing. Search narrowly (file paths, line numbers) and read only the lines you need, at most about 150 at a time; don't print whole large files. Do all searching yourself: don't start helper agents (they can run on the top model and cost more). Batch independent look-ups into one turn. Aim to finish within about 40 actions. Take a screenshot only when the bug is visual, one per check.\n\nEscalation: if after about 60 actions you have neither a failing test or repeatable reproduction nor a confirmed cause, or you can only explain the symptom and not the cause, stop. Save your findings and hand back a first line starting \"ESCALATE: needs the top model\", then what you proved, what you ruled out and where you'd look next. Don't write a speculative fix.\n\nThen fix the root cause. Test first where the engine allows: a test or a repeatable reproduction that fails before the fix and passes after. Keep the change to the bug. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link and the before-and-after evidence.\n\nOn rework from review or playtest: keep the diagnosis unless the feedback says it is wrong; go straight to the fix. If the root cause turns out to be different, don't patch the symptom: say so plainly in your output.\n\nFor the session running this workflow: if this step's hand-back starts 'ESCALATE', don't complete the step. Call fail_step on it with reset_to_step_id = this step and the hand-back as output, then update_step it to model_tier frontier, then claim_next_step again. If the step is already on frontier, stop and ask the person instead.","deliverables":["Reproduction steps","Root cause","Fix","PR link","Before-and-after evidence","Working-notes file"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the fix independently against the root cause in the investigation and the working-notes file. You don't edit code. Check that it fixes the cause rather than the symptom, that the regression test really fails without the fix, and look for security issues, test quality, project conventions and scope creep. Send blocking issues back with fail_step as a numbered list: reset to Investigate and fix, saying whether the diagnosis or the code is wrong. Start your output with 'Pass' or 'Blocked'.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Regression playtest and summary","model_tier":"standard","description":"Follow the original reproduction and confirm the bug is gone, then play the areas around the change for anything it broke. Send failures back with fail_step and reset to Investigate and fix. Then write the summary in plain English. The fix is approved from this step.","deliverables":["Regression playtest report","Plain-English summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Diagnose and fix, check, playtest: one standard-tier engineer finds the root cause and fixes it, handing back to the top model if it can't pin the cause; an independent top-model code review and a regression playtest follow, and you approve the fix.$tpl$,
    updated_at = now()
WHERE name = $tpl$Game Bug Fix$tpl$;
